# Public counterparts of the retained native-grid evidence layers.  They read
# only a fixed, checksum-validated automatic indicator package mounted at
# /data/drought/production-indicators; no development raster path is exposed.

LAYER
  NAME "tigray_drought_chirps_raw_public" TYPE RASTER STATUS OFF
  DATA "/data/drought/production-indicators/current/chirps-current-rainfall.tif"
  METADATA "wms_title" "Tigray Latest Rainfall Total (CHIRPS native grid, retained evidence)" "wms_srs" "EPSG:3857 EPSG:4326" "wms_enable_request" "*" END
  CLASS NAME "Below 50 mm" EXPRESSION ([pixel] < 50) STYLE COLOR 255 247 188 END END
  CLASS NAME "50–100 mm" EXPRESSION (([pixel] >= 50) AND ([pixel] < 100)) STYLE COLOR 254 227 145 END END
  CLASS NAME "100–150 mm" EXPRESSION (([pixel] >= 100) AND ([pixel] < 150)) STYLE COLOR 254 196 79 END END
  CLASS NAME "150–200 mm" EXPRESSION (([pixel] >= 150) AND ([pixel] < 200)) STYLE COLOR 254 153 41 END END
  CLASS NAME "200–250 mm" EXPRESSION (([pixel] >= 200) AND ([pixel] < 250)) STYLE COLOR 236 112 20 END END
  CLASS NAME "250–300 mm" EXPRESSION (([pixel] >= 250) AND ([pixel] < 300)) STYLE COLOR 204 76 2 END END
  CLASS NAME "300–350 mm" EXPRESSION (([pixel] >= 300) AND ([pixel] < 350)) STYLE COLOR 153 52 4 END END
  CLASS NAME "350–400 mm" EXPRESSION (([pixel] >= 350) AND ([pixel] < 400)) STYLE COLOR 102 37 6 END END
  CLASS NAME "400–450 mm" EXPRESSION (([pixel] >= 400) AND ([pixel] < 450)) STYLE COLOR 71 25 8 END END
  CLASS NAME "At least 450 mm" EXPRESSION ([pixel] >= 450) STYLE COLOR 45 18 8 END END
END

