LAYER
  NAME "tigray_drought_ndvi_raw_public" TYPE RASTER STATUS OFF
  DATA "/data/drought/production-indicators/current/ndvi-current.tif"
  METADATA "wms_title" "Tigray Vegetation Condition (Copernicus NDVI native grid, retained evidence)" "wms_srs" "EPSG:3857 EPSG:4326" "wms_enable_request" "*" END
  CLASS NAME "NDVI below 0.10" EXPRESSION ([pixel] < 0.10) STYLE COLOR 165 0 38 END END
  CLASS NAME "NDVI 0.10–0.20" EXPRESSION (([pixel] >= 0.10) AND ([pixel] < 0.20)) STYLE COLOR 215 48 39 END END
  CLASS NAME "NDVI 0.20–0.30" EXPRESSION (([pixel] >= 0.20) AND ([pixel] < 0.30)) STYLE COLOR 244 109 67 END END
  CLASS NAME "NDVI 0.30–0.40" EXPRESSION (([pixel] >= 0.30) AND ([pixel] < 0.40)) STYLE COLOR 253 174 97 END END
  CLASS NAME "NDVI 0.40–0.50" EXPRESSION (([pixel] >= 0.40) AND ([pixel] < 0.50)) STYLE COLOR 254 224 139 END END
  CLASS NAME "NDVI 0.50–0.60" EXPRESSION (([pixel] >= 0.50) AND ([pixel] < 0.60)) STYLE COLOR 217 239 139 END END
  CLASS NAME "NDVI 0.60–0.70" EXPRESSION (([pixel] >= 0.60) AND ([pixel] < 0.70)) STYLE COLOR 166 217 106 END END
  CLASS NAME "NDVI 0.70–0.80" EXPRESSION (([pixel] >= 0.70) AND ([pixel] < 0.80)) STYLE COLOR 102 189 99 END END
  CLASS NAME "NDVI 0.80–0.90" EXPRESSION (([pixel] >= 0.80) AND ([pixel] < 0.90)) STYLE COLOR 26 152 80 END END
  CLASS NAME "NDVI at least 0.90" EXPRESSION ([pixel] >= 0.90) STYLE COLOR 0 104 55 END END
END

