LAYER
  NAME "tigray_drought_wapor_raw_public" TYPE RASTER STATUS OFF
  DATA "/data/drought/production-indicators/current/wapor-transpiration-current.tif"
  METADATA "wms_title" "Tigray Agricultural Water Use (FAO WaPOR transpiration native grid, retained evidence)" "wms_srs" "EPSG:3857 EPSG:4326" "wms_enable_request" "*" END
  CLASS NAME "Transpiration below 0.5 mm/day" EXPRESSION ([pixel] < 0.5) STYLE COLOR 255 247 188 END END
  CLASS NAME "0.5–1.0 mm/day" EXPRESSION (([pixel] >= 0.5) AND ([pixel] < 1.0)) STYLE COLOR 254 227 145 END END
  CLASS NAME "1.0–1.5 mm/day" EXPRESSION (([pixel] >= 1.0) AND ([pixel] < 1.5)) STYLE COLOR 254 196 79 END END
  CLASS NAME "1.5–2.0 mm/day" EXPRESSION (([pixel] >= 1.5) AND ([pixel] < 2.0)) STYLE COLOR 254 153 41 END END
  CLASS NAME "2.0–2.5 mm/day" EXPRESSION (([pixel] >= 2.0) AND ([pixel] < 2.5)) STYLE COLOR 236 112 20 END END
  CLASS NAME "2.5–3.0 mm/day" EXPRESSION (([pixel] >= 2.5) AND ([pixel] < 3.0)) STYLE COLOR 204 76 2 END END
  CLASS NAME "3.0–3.5 mm/day" EXPRESSION (([pixel] >= 3.0) AND ([pixel] < 3.5)) STYLE COLOR 153 52 4 END END
  CLASS NAME "3.5–4.0 mm/day" EXPRESSION (([pixel] >= 3.5) AND ([pixel] < 4.0)) STYLE COLOR 102 37 6 END END
  CLASS NAME "4.0–5.0 mm/day" EXPRESSION (([pixel] >= 4.0) AND ([pixel] < 5.0)) STYLE COLOR 71 25 8 END END
  CLASS NAME "At least 5.0 mm/day" EXPRESSION ([pixel] >= 5.0) STYLE COLOR 45 18 8 END END
END
